class DomainEvent(BaseModel):
    """Canonical envelope for domain and WebSocket events."""

    model_config = ConfigDict(extra="allow")

    type: DomainEventType
    data: dict[str, Any] = Field(default_factory=dict)
    event_id: int | None = None


def validate_event_payload(event_type: str, data: dict[str, Any]) -> BaseModel:
    """Validate an event payload against its generated contract model."""
    model_cls = EVENT_PAYLOAD_MODELS.get(event_type)
    if model_cls is None:
        raise ValueError(f"Unknown domain event type: {event_type!r}")
    return model_cls.model_validate(data)
